<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,toRefs,watch } from 'vue'
import { listen } from '@tauri-apps/api/event'
import { AppWindow,Cable,Check,ChevronDown,Grid2X2,Hash,Layers,ListFilter,Logs,MousePointer2,Plus,Square,TextCursorInput,ToggleLeft,Trash2,Type,X,ChartNoAxesCombined,CircleDot,Search } from 'lucide-vue-next'
import './designer.css'
import StudioToolbar from './components/StudioToolbar.vue'
import { useEditorLayout } from './lib/editor-layout'
import DesignCanvas from './components/DesignCanvas.vue'
import WidgetInspector from './components/WidgetInspector.vue'
import DesignSystemPanel from './components/DesignSystemPanel.vue'
import FlowEditor from './components/FlowEditor.vue'
import ResourcesPanel from './components/ResourcesPanel.vue'
import ObjectTree from './components/ObjectTree.vue'
import LanguagePanel from './components/LanguagePanel.vue'
import ContextMenu from './components/ContextMenu.vue'
import BaseButton from './components/base/BaseButton.vue'
import { useEditor,parseProject } from './lib/editor'
import { call,desktop,getEnvironment,pickFile,pickSave,useRuntime,validate } from './lib/backend'
import { clone,createNode,createWidget,emptyProject,newId,widgetKinds,type Environment,type Project,type ValidationIssue } from './lib/model'
import { refreshAssets } from './lib/resources'
import { platformLabel } from './lib/platform'
import { connectWorkspace,editorWindowId,workspaceRevision,workspacePath,workspaceRecovered,workspaceMissingDependencies,type WorkspaceState } from './lib/workspace'
import { browserProjectPackage,downloadProjectPackage } from './lib/project-package'
import { projectLocale,t } from './lib/i18n'
import type { MenuItem } from './lib/context-menu'
const isLogicWindow=editorWindowId==='logic',runtime=useRuntime(),editor=useEditor(parseProject(JSON.stringify(emptyProject())))
const paletteFilter=ref(''),activeLibrary=ref('widgets'),environment=ref<Environment>(),issues=ref<ValidationIssue[]>([]),pending=ref(false),resources=ref<InstanceType<typeof ResourcesPanel>>(),canvas=ref<InstanceType<typeof DesignCanvas>>(),fileInput=ref<HTMLInputElement>(),assetInput=ref<HTMLInputElement>(),toast=ref(''),toastError=ref(false),help=ref(false),languagesOpen=ref(false),placement=ref(''),focusNodeId=ref(''),projectPath=workspacePath
const layout=useEditorLayout(isLogicWindow?'logic':'main')
const {leftCollapsed,rightCollapsed,resourcesExpanded:expanded,resourceTab}=toRefs(layout.preferences)
const {sizes}=layout
const foldedGroups=ref<string[]>([])
const serialMatches=computed(()=>!paletteFilter.value.trim()||`串口控制面板 serial-panel ${t('串口控制面板')}`.toLowerCase().includes(paletteFilter.value.trim().toLowerCase()))
function toggleGroup(group:string){foldedGroups.value=foldedGroups.value.includes(group)?foldedGroups.value.filter(item=>item!==group):[...foldedGroups.value,group]}
const contextMenu=ref<{x:number;y:number;items:MenuItem[]}>(),renamingPage=ref('')
let toastTimeout:ReturnType<typeof setTimeout>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined,draggingPalette=false,offFocus:(()=>void)|undefined
const icons:Record<string,any>={Type,MousePointer2,TextCursorInput,Hash,ListFilter,ToggleLeft,CircleDot,Square,ChartNoAxesCombined,Logs}
const filteredWidgets=computed(()=>widgetKinds.filter(widget=>`${widget.label} ${t(widget.label)} ${widget.kind}`.toLowerCase().includes(paletteFilter.value.toLowerCase())))
const groups=computed(()=>[...new Set(filteredWidgets.value.map(widget=>widget.group))])
function notify(message:string,error=false){toast.value=message;toastError.value=error;if(toastTimeout)clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.value='',error?10000:3500)}
const report=(error:unknown)=>notify(String(error).replace(/^Error:\s*/,''),true)
const workspace=connectWorkspace(editor,report)
async function perform(task:()=>Promise<unknown>){if(pending.value)return;pending.value=true;try{await task()}catch(error){report(error)}finally{pending.value=false}}
async function saveProject(forcePath=false):Promise<boolean>{await workspace.flush();const snapshot=workspace.snapshot;if(!desktop){await downloadProjectPackage(snapshot.project);workspaceMissingDependencies.value=[...browserProjectPackage.missingDependencies];await workspace.markSaved(snapshot.revision,snapshot.project);notify(t('工程包已保存'));return true}const path=!forcePath&&projectPath.value?.endsWith('.hmiproj')?projectPath.value:await pickSave(editor.project.value.name);if(!path)return false;const state=await call<WorkspaceState>('save_workspace_package',{path});await workspace.receive(state);notify(t('工程包已保存'));return true}
function canReplace(){return !editor.dirty.value||window.confirm(t('当前项目有未保存修改，确定替换当前项目？'))}
async function newProject(){if(!canReplace())return;if(runtime.running.value)await runtime.stop();await workspace.replace(emptyProject());issues.value=[];placement.value=''}
async function openProject(){if(!canReplace())return;if(!desktop){fileInput.value?.click();return}const path=await pickFile('project');if(!path)return;if(runtime.running.value)await runtime.stop();await workspace.flush();const state=await call<WorkspaceState>(path.toLowerCase().endsWith('.json')?'import_legacy_project':'open_workspace_package',{path});await workspace.receive(state);issues.value=[];await refreshAssets(editor.project.value);notify(t('项目已打开'))}
async function browserOpen(event:Event){const input=event.target as HTMLInputElement;try{const file=input.files?.[0];if(file){const project=await browserProjectPackage.open(file);await workspace.replace(project);workspaceMissingDependencies.value=[...browserProjectPackage.missingDependencies];await refreshAssets(project);issues.value=[];notify(t('项目已打开'))}}catch(error){report(error)}finally{input.value=''}}
async function check(){await workspace.flush();if(!desktop){parseProject(JSON.stringify(editor.project.value));issues.value=[];notify(t('项目格式检查通过；完整流程与代码校验请使用桌面版'));return}issues.value=await validate(editor.project.value);if(issues.value.some(issue=>issue.severity==='error'))resources.value?.showIssues();notify(issues.value.some(issue=>issue.severity==='error')?t('项目存在问题，请查看检查面板'):t('项目检查通过'),issues.value.some(issue=>issue.severity==='error'))}
async function preview(){if(!desktop)throw Error(t('浏览器模式支持设计。请启动桌面版进行真实预览和设备通信。'));await workspace.flush();if(!runtime.running.value){issues.value=await validate(editor.project.value);if(issues.value.some(issue=>issue.severity==='error')){resources.value?.showIssues();throw Error(t('项目检查未通过，请先修复检查面板中的错误'))}}await runtime.openPreview(clone(editor.project.value));notify(t('预览窗口已打开，修改将自动同步'))}
async function exportProject(){if(!(await saveProject()))return;const destination=await pickSave(editor.project.value.name,true);if(!destination)return;const result=await call<{path:string;files:number;includesPython:boolean}>('export_project',{project:editor.project.value,destination});notify(`${t('运行包已生成')}：${result.path}`)}
async function importResource(kind:'plugin'|'python'|'dependencies'){const path=await pickFile('directory');if(!path)return;const result=await call<Project['python']>(kind==='plugin'?'import_plugin':kind==='python'?'import_python_runtime':'import_python_dependencies',{path});if(result&&(kind==='dependencies'||kind==='python'&&editor.project.value.flows.some(flow=>flow.nodes.some(node=>node.kind==='python'))))editor.mutate(project=>{project.python=kind==='python'&&project.python?.runtimeId===result.runtimeId?{...project.python,runtimeSha256:result.runtimeSha256}:result});await workspace.flush();await resources.value?.refresh();environment.value=await getEnvironment();notify(t('资源已导入'))}
async function importAsset(){if(!desktop){assetInput.value?.click();return}const path=await pickFile('asset');if(!path)return;const result=await call<{id:string;path:string}>('import_asset',{path});editor.mutate(project=>{project.assets??=[];project.assets.push({id:result.id,path:result.path})});await workspace.flush();await refreshAssets(editor.project.value);notify(t('资源已导入'))}
async function browserAsset(event:Event){const input=event.target as HTMLInputElement;try{const file=input.files?.[0];if(file){const result=await browserProjectPackage.addAsset(file,editor.project.value);editor.mutate(project=>{project.assets??=[];project.assets.push(result)});await refreshAssets(editor.project.value)}}catch(error){report(error)}finally{input.value=''}}
function addPage(){const id=newId('page');editor.mutate(project=>project.pages.push({id,name:t('新页面'),widgets:[],layout:{type:'absolute'},responsive:true,guides:[]}));editor.pageId.value=id;editor.selected.value=[]}
function removePage(id=editor.pageId.value){if(editor.project.value.pages.length<2)return;editor.mutate(project=>project.pages=project.pages.filter(page=>page.id!==id));if(editor.pageId.value===id)editor.pageId.value=editor.project.value.pages[0]!.id;editor.selected.value=[]}
function pageContext(event:MouseEvent,id:string){event.preventDefault();contextMenu.value={x:event.clientX,y:event.clientY,items:[{label:'新建页面',action:addPage},{label:'复制副本',action:()=>{const source=editor.project.value.pages.find(page=>page.id===id);if(!source)return;const page=clone(source),ids=new Map(page.widgets.map(widget=>[widget.id,newId('widget')]));page.id=newId('page');page.name+=' 副本';for(const widget of page.widgets){const old=widget.id;widget.id=ids.get(old)!;if(widget.parentId)widget.parentId=ids.get(widget.parentId)}editor.mutate(project=>project.pages.push(page));editor.pageId.value=page.id}},{label:'重命名',action:()=>renamingPage.value=id},{label:'删除',disabled:editor.project.value.pages.length<2,action:()=>removePage(id)}]}}
function renamePage(id:string,name:string){if(name.trim())editor.mutate(project=>{const page=project.pages.find(page=>page.id===id);if(page)page.name=name.trim()});renamingPage.value=''}
function addSerialPanel(x:number,y:number,parentId?:string,slotId?:string){editor.mutate(project=>{let connection=project.connections[0];if(!connection){connection={id:newId('connection'),name:t('串口连接'),port:'',baudRate:115200,dataBits:8,stopBits:1,parity:'none',protocolId:'',protocolVersion:'1.0.0',protocolConfig:{}};project.connections.push(connection)}const group=createWidget('group',x,y);group.props.text=t('设备连接');group.width=360;group.height=150;group.parentId=parentId;group.slotId=slotId;project.pages.find(page=>page.id===editor.pageId.value)!.widgets.push(group);for(const [index,kind]of ['connection.open','connection.close'].entries()){const trigger=createNode('trigger.ui'),action=createNode(kind,{x:340,y:80}),flowId=newId('flow');action.config.connectionId=connection.id;project.flows.push({id:flowId,name:index?t('关闭连接'):t('打开连接'),enabled:true,timeoutMs:30000,nodes:[trigger,action],edges:[{id:newId('edge'),source:trigger.id,sourcePort:'out',target:action.id,targetPort:'in'}]});const button=createWidget('button',20+index*160,58);button.parentId=group.id;button.slotId='content';button.props.text=index?t('关闭连接'):t('打开连接');button.events.click={kind:'flow',flowId,entryNodeId:trigger.id};editor.page.value.widgets.push(button)}editor.selected.value=[group.id]});resources.value?.showConnections()}
async function openLogic(flowId?:string,nodeId?:string){await workspace.flush();placement.value='';if(desktop)await call('open_logic_window',{flowId,nodeId});else{const url=new URL(location.href);url.searchParams.set('view','logic');if(flowId)url.searchParams.set('flowId',flowId);if(nodeId)url.searchParams.set('nodeId',nodeId);const popup=window.open(url.toString(),'hmi-logic','width=1280,height=820');if(!popup)throw Error('逻辑窗口被浏览器拦截');popup.focus()}}
function armPlacement(kind:string){if(draggingPalette)return;placement.value=placement.value===kind?'':kind}
function paletteDrag(event:DragEvent,kind:string){draggingPalette=true;placement.value=kind;event.dataTransfer?.setData('application/hmi-widget',kind)}
function paletteDragEnd(){setTimeout(()=>{draggingPalette=false;placement.value=''},0)}
const resizePanel=layout.resize
function keydown(event:KeyboardEvent){if(event.key==='Escape'){help.value=false;languagesOpen.value=false;placement.value='';contextMenu.value=undefined}const target=event.composedPath()[0] as HTMLElement;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void perform(()=>saveProject());return}if(target?.closest('input,textarea,select,[contenteditable=true]'))return;if(event.ctrlKey||event.metaKey){const key=event.key.toLowerCase();if(key==='z'){event.preventDefault();event.shiftKey?editor.redo():editor.undo()}if(key==='y'){event.preventDefault();editor.redo()}if(key==='d'&&!isLogicWindow){event.preventDefault();editor.duplicateSelected()}}else if((event.key==='Delete'||event.key==='Backspace')&&!isLogicWindow){event.preventDefault();editor.removeSelected()}}
function beforeUnload(event:BeforeUnloadEvent){if(editor.dirty.value&&!isLogicWindow){event.preventDefault();event.returnValue=''}}
watch(editor.project,()=>{if(isLogicWindow||!runtime.running.value)return;if(previewTimer)clearTimeout(previewTimer);previewTimer=setTimeout(async()=>{try{await workspace.flush();const result=await runtime.updatePreview(clone(editor.project.value),workspaceRevision.value);if(result?.issues)issues.value=result.issues}catch(error){report(error)}},300)},{deep:true})
watch(projectLocale,locale=>{if(!isLogicWindow&&desktop&&runtime.running.value)void call('set_preview_locale',{locale}).catch(report)})
onMounted(async()=>{window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload);try{if(desktop)environment.value=await getEnvironment();await workspace.init();if(workspaceRecovered.value)notify(t('已恢复未保存工程'));await refreshAssets(editor.project.value);if(editor.project.value.i18n)projectLocale.value=editor.project.value.i18n.defaultLocale;if(desktop)await runtime.connectPreview();if(isLogicWindow){const query=new URLSearchParams(location.search);if(query.get('flowId'))editor.flowId.value=query.get('flowId')!;focusNodeId.value=query.get('nodeId')??'';if(desktop)offFocus=await listen<{flowId?:string;nodeId?:string}>('logic-focus',event=>{if(event.payload.flowId)editor.flowId.value=event.payload.flowId;focusNodeId.value=event.payload.nodeId??''})}}catch(error){report(error)}})
onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload);workspace.dispose();runtime.dispose();offFocus?.();if(toastTimeout)clearTimeout(toastTimeout);if(previewTimer)clearTimeout(previewTimer)})
</script>
<template>
 <div class="studio-shell" :class="{'logic-editor-shell':isLogicWindow}" :style="{'--library-width':`${sizes.leftWidth}px`,'--inspector-width':`${sizes.rightWidth}px`,'--resources-height':`${sizes.resourceHeight}px`}">
  <StudioToolbar :editor="editor" :logic="isLogicWindow" :desktop="desktop" :pending="pending" :running="runtime.running.value" :busy="runtime.busy.value" :left-collapsed="leftCollapsed" :right-collapsed="rightCollapsed"
    @new="perform(newProject)" @open="perform(openProject)" @save="force=>perform(()=>saveProject(force))" @import="kind=>perform(()=>importResource(kind))" @asset="perform(importAsset)" @languages="languagesOpen=true" @help="help=true" @reset="layout.reset" @logic="perform(()=>openLogic())" @check="perform(check)" @preview="perform(preview)" @stop="perform(runtime.stop)" @export="perform(exportProject)" @toggle-left="leftCollapsed=!leftCollapsed" @toggle-right="rightCollapsed=!rightCollapsed"/>
  <div v-if="workspaceMissingDependencies.length" class="missing-resource-notice" role="status"><strong>{{ t('缺少工程资源') }}：</strong><span data-project-text>{{ workspaceMissingDependencies.join(', ') }}</span><span>{{ t('请通过文件菜单导入资源后再预览或导出。') }}</span></div>
  <div class="studio-workspace" :class="{'left-collapsed':leftCollapsed,'right-collapsed':rightCollapsed}"><template v-if="!isLogicWindow"><aside v-show="!leftCollapsed" class="library"><div class="library-tabs"><button :class="{active:activeLibrary==='widgets'}" @click="activeLibrary='widgets'"><Grid2X2 :size="15"/>{{ t('组件') }}</button><button :class="{active:activeLibrary==='layers'}" @click="activeLibrary='layers'"><Layers :size="15"/>{{ t('图层') }}</button><button :class="{active:activeLibrary==='design'}" @click="activeLibrary='design'">设计系统</button></div><div v-if="activeLibrary==='widgets'" class="library-search"><Search :size="14"/><input v-model="paletteFilter" :placeholder="t('搜索组件…')" :aria-label="t('搜索组件')"/></div><div class="library-content"><template v-if="activeLibrary==='widgets'"><template v-for="group in groups" :key="group"><button class="library-section-heading library-group-toggle" :aria-expanded="!!paletteFilter.trim()||!foldedGroups.includes(group)" @click="toggleGroup(group)"><ChevronDown :size="12" :class="{folded:!paletteFilter.trim()&&foldedGroups.includes(group)}"/>{{ t(group) }}</button><div v-show="paletteFilter.trim()||!foldedGroups.includes(group)" class="widget-library"><button v-for="widget in filteredWidgets.filter(item=>item.group===group)" :key="widget.kind" class="widget-library-item" :class="{active:placement===widget.kind}" draggable="true" @dragstart="paletteDrag($event,widget.kind)" @dragend="paletteDragEnd" @click="armPlacement(widget.kind)"><component :is="icons[widget.icon]??Square" :size="16" :stroke-width="1.5"/><span>{{ t(widget.label) }}</span></button></div></template><div v-if="serialMatches" class="library-section-heading">{{ t('设备组件') }}</div><button v-if="serialMatches" class="serial-library-item" draggable="true" @dragstart="paletteDrag($event,'serial-panel')" @dragend="paletteDragEnd" @click="armPlacement('serial-panel')"><Cable :size="16"/><span>{{ t('串口控制面板') }}</span><Plus :size="14"/></button><p v-if="!filteredWidgets.length&&!serialMatches" class="palette-empty">{{ t('没有匹配的组件') }}</p></template><ObjectTree v-else-if="activeLibrary==='layers'" :editor="editor" @context="(event,id)=>canvas?.openContext(event,id)"/><DesignSystemPanel v-else :editor="editor" :canvas="canvas?.$el as HTMLElement"/></div><div class="pages-panel"><div class="panel-title">{{ t('页面') }}<button class="icon-button" title="添加页面" @click="addPage"><Plus :size="15"/></button></div><div v-for="page in editor.project.value.pages" :key="page.id" class="page-item" :class="{active:editor.pageId.value===page.id}" @contextmenu="pageContext($event,page.id)"><input v-if="renamingPage===page.id" :value="page.name" autofocus @change="renamePage(page.id,($event.target as HTMLInputElement).value)" @blur="renamingPage=''" @keydown.enter="renamePage(page.id,($event.target as HTMLInputElement).value)"/><button v-else @click="editor.pageId.value=page.id;editor.selected.value=[];placement=''"><AppWindow :size="15"/><span data-project-text>{{ page.name }}</span><span class="page-count">{{ page.widgets.length }}</span></button></div><button v-if="editor.project.value.pages.length>1" class="text-button page-remove" @click="removePage()"><Trash2 :size="12"/>{{ t('删除当前页面') }}</button></div></aside><DesignCanvas ref="canvas" :editor="editor" :placement="placement" @placed="placement=''" @serial-panel-drop="addSerialPanel" @logic="(flowId,nodeId)=>perform(()=>openLogic(flowId,nodeId))" @error="report"/><WidgetInspector v-show="!rightCollapsed" :editor="editor"/></template><FlowEditor v-else :editor="editor" :focus-node-id="focusNodeId" :events="runtime.events.value" :running="runtime.running.value" @error="report" @run="(flowId,nodeId)=>perform(()=>runtime.act({kind:'flow',flowId,entryNodeId:nodeId}))"/><div v-if="!leftCollapsed" class="pane-resizer left" @pointerdown="resizePanel($event,'left')"/><div v-if="!rightCollapsed" class="pane-resizer right" @pointerdown="resizePanel($event,'right')"/></div>
  <div v-if="expanded" class="resource-resizer" @pointerdown="resizePanel($event,'bottom')"/><ResourcesPanel ref="resources" v-model:expanded="expanded" v-model:active-tab="resourceTab" :editor="editor" :runtime="runtime" :issues="issues" @error="report" @import-plugin="perform(()=>importResource('plugin'))">
    <template #status><div class="dock-status" :title="t(desktop?'桌面工作区':'浏览器设计模式')"><span class="status-ready"><i :class="{running:runtime.running.value}"/>{{ t(pending?'正在处理…':runtime.running.value?'运行中':'就绪') }}</span><span v-if="runtime.running.value" class="preview-status">{{ t(runtime.updateStatus.value==='waiting'?'等待更新':runtime.updateStatus.value==='invalid'?'校验失败':'已更新') }} · r{{ runtime.revision.value }}</span><span class="dock-filename" :title="projectPath??t('未保存到项目文件')" data-project-text>{{ projectPath?.split(/[\\/]/).pop()??t('未保存到项目文件') }}</span></div></template>
  </ResourcesPanel>
  <input ref="fileInput" type="file" accept=".hmiproj,.json" hidden @change="browserOpen"/><input ref="assetInput" type="file" accept=".png,.jpg,.jpeg,.webp,.gif,.woff,.woff2,.ttf,.otf" hidden @change="browserAsset"/>
  <LanguagePanel v-if="languagesOpen" :editor="editor" @close="languagesOpen=false" @error="report"/>
  <div v-if="help" class="modal-backdrop" @click.self="help=false"><section class="help-dialog" role="dialog" aria-modal="true" aria-label="开始使用"><div class="inline-between"><h2>{{ t('开始搭建你的上位机') }}</h2><button class="icon-button" title="关闭帮助" @click="help=false"><X :size="18"/></button></div><ol><li>{{ t('将组件拖到画布，释放时定位；点击组件库后也可点击画布放置。') }}</li><li>{{ t('右键组件配置对齐、布局和事件；滚轮缩放，空格拖动平移。') }}</li><li>{{ t('打开独立逻辑窗口，同时编辑界面、流程和 Python。') }}</li><li>{{ t('运行预览后，校验通过的修改自动更新。保存会生成包含资源和依赖的完整工程包。') }} {{ platformLabel }} {{ t('程序') }}</li></ol><BaseButton appearance="primary" @click="help=false">{{ t('开始设计') }}</BaseButton></section></div>
  <ContextMenu v-if="contextMenu" v-bind="contextMenu" @close="contextMenu=undefined"/>
 </div>
 <div v-if="toast" class="toast" :class="{error:toastError}" role="status"><CircleDot v-if="toastError" :size="18"/><Check v-else :size="18"/><span>{{ toast }}</span><button class="icon-button" title="关闭提示" @click="toast=''"><X :size="14"/></button></div>
</template>
